/*
 * A107337  Substitution 1->{1, 2, 1, 3, 2, 3, 1}, 2->{3}, 3->{1}, starting
 *          with 1.
 * https://oeis.org/A107337
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the symbol at position n in the infinite word *
 *            generated by the morphism * 1 → 1 2 1 3 2 3 1 * 2 → 3 * 3 → 1 *
 *            starting with the word [1]. * The first terms are a(0)=1,
 *            a(1)=2, a(2)=1, a(3)=3, …
 * Range:     u8 n <= 104, u16 n <= 104, u32 n <= 104, u64 n <= 104,
 *            u128 n <= 104, big any n
 * Helpers:   grow_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include "../utils/grow_array.h"

/* Static storage for the generated word.  The array grows lazily so
 * that a call to a(n) only computes as many symbols as necessary.  */
static seq_t *seq = NULL;
static idx_t seq_len = 0;

/* Ensure that seq contains at least n + 1 symbols (indices 0 … n). */
static void ensure_len(idx_t n)
{
    if (seq == NULL) {
        seq = (seq_t *)malloc(sizeof(seq_t));
        if (!seq) return;                /* allocation failure */
        seq[0] = (seq_t)1;
        seq_len = 1;
    }

    while (seq_len <= n) {
        /* Approximately bound the new length (each old *1* can become 7
         * symbols, others stay 1).  Add a small buffer to avoid
         * re‑allocation for every insertion. */
        idx_t new_cap = seq_len * 7 + 5;
        seq_t *tmp = (seq_t *)malloc(sizeof(seq_t) * new_cap);
        if (!tmp) return;                /* allocation failure */

        idx_t pos = 0;
        for (idx_t i = 0; i < seq_len; ++i) {
            seq_t v = seq[i];
            if (v == (seq_t)1) {
                /* 1 → 1 2 1 3 2 3 1 */
                tmp[pos++] = (seq_t)1;
                tmp[pos++] = (seq_t)2;
                tmp[pos++] = (seq_t)1;
                tmp[pos++] = (seq_t)3;
                tmp[pos++] = (seq_t)2;
                tmp[pos++] = (seq_t)3;
                tmp[pos++] = (seq_t)1;
            } else if (v == (seq_t)2) {
                /* 2 → 3 */
                tmp[pos++] = (seq_t)3;
            } else { /* v == 3 */
                /* 3 → 1 */
                tmp[pos++] = (seq_t)1;
            }
        }
        free(seq);
        seq = tmp;
        seq_len = pos;
    }
}

seq_t a(idx_t n)
{
    ensure_len(n);           /* guarantee seq[n] exists */
    return seq[n];
}
